contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to capture whether a caller other than owner can successfully make sendTo transfer funds.
    // Parameters:
    // - callerIsOwner: if true, the calling account is assumed to be the owner; if false, it's assumed to be a different account.
    // - receiver: destination address passed to sendTo
    // - amount: amount passed to sendTo
    // This function must be invoked in a test harness that sets msg.sender appropriately (i.e., the harness calls this function from different accounts).
    function run(bool callerIsOwner, address payable receiver, uint256 amount) public {
        // Preconditions: receiver must be non-zero and amount > 0 to reach transfer in both P and M.
        require(receiver != address(0));
        require(amount > 0);

        // Ensure this contract has enough balance if it is the caller that will cause a transfer from c.
        // The harness must ensure address(this) has enough balance if necessary for any payable interactions.

        // We attempt the call; the success/failure is captured by the returned boolean.
        // According to original contract P, only the owner can make sendTo succeed; non-owner calls revert.
        // According to mutant M, non-owners can also make sendTo succeed.
        bool success;
        // Make the external call to c.sendTo and capture whether it reverted.
        // Using low-level call to obtain a boolean success indicator while still invoking the intended public function.
        (success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // The property to assert: if the caller is not the owner, the call must fail (i.e., not succeed).
        // This distinguishes P (enforces it) from M (which would allow success for non-owners).
        if (!callerIsOwner) {
            assert(!success);
        } else {
            // If callerIsOwner, we make no strong claim about success here (it may depend on balances),
            // so simply assert true for the owner case by asserting success || true is redundant; instead do nothing.
            assert(true);
        }
    }

    // Allow the contract to receive ether if the harness funds it.
    receive() external payable {}
}

