    // but is violated by the mutant M in cases where .call returns false but does not revert the same way (we detect by using low-level call's success boolean via try/catch).

    function check(address ownerCaller, address receiver, uint amount) public {
        // Preconditions for meaningful call
        require(ownerCaller != address(0));
        require(receiver != address(0));
        require(amount > 0);

        // Ensure this contract has enough balance to forward if needed
        require(address(this).balance >= amount);

        // Call c.sendTo as the ownerCaller by using a low-level call from this contract
        // We cannot change msg.sender, so we require that the owner of c equals ownerCaller by checking revert via a simulated call.
        // First, check that calling sendTo from this contract would not revert because of wrong sender: the test harness expects ownerCaller==address(this)
        // So require the provided ownerCaller equals address(this) to make this call exercise the send path.
        require(ownerCaller == address(this));

        bool didRevert;
        // Perform the state-changing call on c; must be top-level statement.
        try c.sendTo{value: amount}(receiver, amount) {
            didRevert = false;
